from pathlib import Path
from html import escape
from urllib.parse import quote
import base64
import io
import re
import zipfile

# De WebP-afbeeldingen zijn meegeleverd, zodat geen extra installatie nodig is.
ASSETS_B64 = ""
p = Path("winkel.html")
if not p.exists():
    raise SystemExit("Open eerst de projectmap makers-3d-labs.")
html = p.read_text(encoding="utf-8")
if 'id="shop-search"' not in html or 'id="makers-webshop-categorieen"' not in html:
    raise SystemExit("Voer eerst werk-webshop-bij.py uit. Er is niets gewijzigd.")

categories = [
 ("kerst", "Kerst", "categorie-kerst.webp", "Persoonlijke decoratie en kerstcadeaus"),
 ("zakelijk", "Zakelijk", "categorie-zakelijk.webp", "Bedrijfsdisplays, QR-standaards en logo-artikelen"),
 ("voetbal", "Voetbal", "categorie-voetbal.webp", "Stadionmodellen en supportersartikelen"),
 ("resin", "Resin", "categorie-resin.webp", "Gedetailleerde beelden en miniaturen"),
 ("laser", "Lasergravure", "categorie-lasergravure.webp", "Persoonlijke gravures op hout en metaal"),
 ("bloemenvazen", "Bloemenvazen", "categorie-bloemenvazen.webp", "Decoratieve vazen op aanvraag"),
 ("persoonlijk", "Gepersonaliseerd", "categorie-gepersonaliseerd.webp", "Namen, teksten en persoonlijke cadeaus"),
 ("maskers", "Maskers", "categorie-maskers.webp", "Decoratieve en cosplaymaskers op aanvraag"),
]
items = []
for key, name, filename, alt in categories:
    badge = '<small>Op aanvraag</small>' if key in ("bloemenvazen", "maskers") else '<small>Bekijk producten →</small>'
    items.append('<button class="shop-category-card" type="button" data-shop-category="' + key + '" aria-pressed="false"><img src="' + filename + '" alt="' + escape(alt, quote=True) + '" width="1254" height="1254" loading="lazy"><span>' + name + '</span>' + badge + '</button>')
section = '''<section id="shop-category-gallery" aria-labelledby="shop-category-title">
<h2 id="shop-category-title">Shop per categorie</h2>
<p class="shop-category-intro">Kies een categorie en ontdek de producten. De foto's laten voorbeelden van de mogelijkheden zien.</p>
<div class="shop-category-grid">''' + "".join(items) + '''</div></section>'''
html = re.sub(r'<section id="shop-category-gallery".*?</section>', '', html, flags=re.S)
marker = '<section class="shop-filter-panel"'
if marker not in html:
    raise SystemExit("Zoek- en filterbalk niet gevonden. Er is niets gewijzigd.")
html = html.replace(marker, section + "\n" + marker, 1)
reset = '<div class="shop-filter-buttons"><button type="button" data-shop-category="alles" aria-pressed="true">Alle producten</button></div>'
html, count = re.subn(r'<div class="shop-filter-buttons"[^>]*>.*?</div>', lambda _: reset, html, count=1, flags=re.S)
if count != 1:
    raise SystemExit("Categorieknoppen niet gevonden. Er is niets gewijzigd.")
if 'id="shop-category-request"' not in html:
    html = html.replace('</p>\n</section>\n<div class="mk-grid">', '</p>\n<div id="shop-category-request" hidden></div>\n</section>\n<div class="mk-grid">', 1)
    if 'id="shop-category-request"' not in html:
        html = html.replace('<div class="mk-grid">', '<div id="shop-category-request" hidden></div>\n<div class="mk-grid">', 1)

css = '''<style id="shop-category-gallery-style">
#shop-category-gallery{margin:30px 0 24px}
#shop-category-gallery h2{color:#fff;font-size:clamp(24px,3vw,32px);line-height:1.2;margin:0 0 10px}
#shop-category-gallery .shop-category-intro{color:#c4d3df;font-size:14px;max-width:750px;margin:0 0 20px}
.shop-category-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.shop-category-card{display:flex;flex-direction:column;align-items:stretch;text-align:left;min-width:0;overflow:hidden;padding:0;background:#223244;border:1px solid #607b8e;border-radius:14px;color:#fff;font:inherit;cursor:pointer}
.shop-category-card img{display:block;width:100%;height:auto;aspect-ratio:1;object-fit:cover;background:#152330}
.shop-category-card span{padding:13px 14px 3px;font-size:17px;font-weight:750}
.shop-category-card small{padding:0 14px 14px;color:#9ccdd5;font-size:12px}
.shop-category-card:hover{border-color:#79d6db;background:#2a4053}
.shop-category-card[aria-pressed="true"]{border:2px solid #6dd6d9;box-shadow:0 0 0 2px #6dd6d922}
.shop-category-card[aria-pressed="true"] span{color:#8ce1e4}
.shop-category-card:focus-visible{outline:3px solid #8ce1e4;outline-offset:4px}
#shop-category-request{margin:18px 0 25px;padding:22px;border:1px solid #7298a3;border-radius:14px;background:#203749;color:#e7f0f6}
#shop-category-request h3{margin:0 0 8px;color:#fff;font-size:21px}
#shop-category-request p{color:#c4d3df;font-size:14px;margin:0 0 16px}
#shop-category-request a{display:inline-block;background:#00afb8;color:#082d34;padding:11px 18px;border-radius:9px;text-decoration:none;font-weight:750}
#shop-category-request[hidden]{display:none!important}
@media(max-width:800px){.shop-category-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.shop-category-card span{font-size:16px}}
@media(max-width:350px){.shop-category-card span{font-size:14px;padding:10px 9px 3px}.shop-category-card small{padding:0 9px 12px;font-size:11px}}
@media(prefers-reduced-motion:reduce){.shop-category-card{transition:none}}
</style>'''
html = re.sub(r'<style id="shop-category-gallery-style">.*?</style>', '', html, flags=re.S)
html = html.replace("</head>", css + "\n</head>", 1)
script = r'''<script id="makers-webshop-categorieen">
(function(){
 const search=document.getElementById('shop-search'),grid=document.querySelector('.mk-shop-page .mk-grid');
 if(!search||!grid)return;
 const buttons=Array.from(document.querySelectorAll('[data-shop-category]'));
 const mapping={
  'kersthangers.html':['kerst','persoonlijk'],
  'kersthangers-bedrijfslogo.html':['kerst','zakelijk','persoonlijk'],
  'persoonlijke-kersttafel.html':['kerst','persoonlijk'],
  'kleine-cadeaus.html':['kerst','persoonlijk','laser'],
  'voetbalstadion-deluxe.html':['voetbal','persoonlijk'],
  'samurai-oni-deluxe.html':['resin'],
  'horus-antiekgouden-buste.html':['resin'],
  'anubis-antiekgouden-buste.html':['resin'],
  'bastet-antiekgouden-buste.html':['resin'],
  'business-collection-bedrijfsdisplays.html':['zakelijk','persoonlijk'],
  'clipper-duo-set.html':['persoonlijk'],
  'metalen-supporterskaart-premium.html':['laser','voetbal','persoonlijk']
 };
 const cards=Array.from(grid.querySelectorAll('.mk-product')).map(card=>{
  const link=card.querySelector('a[href]'),href=link?link.getAttribute('href').split(/[?#]/)[0]:'';
  return {card,categories:mapping[href]||[],text:card.textContent.toLocaleLowerCase('nl-NL')};
 });
 const requested={
  bloemenvazen:{title:'Bloemenvazen op maat',text:'Wil je een decoratieve vaas in een bijzondere vorm? Vertel ons je gewenste model, kleur en formaat. We bevestigen vooraf de uitvoering, prijs en mogelijkheden.',product:'Bloemenvazen'},
  maskers:{title:'Maskers op maat',text:'Vraag een decoratief of cosplaymasker aan. Geef het ontwerp, de maat en gewenste afwerking door; we bevestigen de mogelijkheden en prijs vooraf.',product:'Maskers'}
 };
 let active='alles';
 function update(){
  const q=search.value.trim().toLocaleLowerCase('nl-NL');
  let count=0;
  cards.forEach(item=>{const show=(active==='alles'||item.categories.includes(active))&&(!q||item.text.includes(q));item.card.hidden=!show;if(show)count++;});
  buttons.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.shopCategory===active)));
  const request=document.getElementById('shop-category-request'),special=requested[active];
  request.replaceChildren();request.hidden=!special;
  if(special){
   const heading=document.createElement('h3');heading.textContent=special.title;
   const text=document.createElement('p');text.textContent=special.text;
   const link=document.createElement('a');link.href='contact.html?product='+encodeURIComponent(special.product)+'#quoteForm';link.textContent='Vraag jouw ontwerp aan →';
   request.append(heading,text,link);
  }
  document.getElementById('shop-filter-count').textContent=special?'Deze categorie is beschikbaar op aanvraag.':count+' van '+cards.length+' producten';
  document.getElementById('shop-filter-empty').hidden=count>0||Boolean(special);
 }
 buttons.forEach(button=>button.addEventListener('click',()=>{
  active=button.dataset.shopCategory;search.value='';update();
 }));
 search.addEventListener('input',update);
 update();
})();
</script>'''
html, count = re.subn(r'<script id="makers-webshop-categorieen">.*?</script>', lambda _: script, html, count=1, flags=re.S)
if count != 1:
    raise SystemExit("Filterscript niet gevonden. Er is niets gewijzigd.")

contact = Path("contact.html")
contact_html = contact.read_text(encoding="utf-8") if contact.exists() else None
if contact_html is not None:
    prefill = r'''<script id="categorie-maatwerk-aanvraag">
(function(){
 const name=new URLSearchParams(location.search).get('product');
 if(!['Bloemenvazen','Maskers'].includes(name))return;
 const pick=document.getElementById('product'),details=document.getElementById('omschrijving');
 if(!pick||!details)return;
 if(!Array.from(pick.options).some(o=>o.value===name)){const option=document.createElement('option');option.value=name;option.textContent=name;pick.append(option);}
 pick.value=name;
 details.placeholder=name==='Bloemenvazen'?'Beschrijf de gewenste vaas: model, kleur, formaat en eventueel het gebruik met droogbloemen of verse bloemen.':'Beschrijf het masker: ontwerp, maat, kleur en gewenste afwerking.';
})();
</script>'''
    contact_html = re.sub(r'<script id="categorie-maatwerk-aanvraag">.*?</script>', '', contact_html, flags=re.S)
    contact_html = contact_html.replace("</body>", prefill + "\n</body>", 1)

allowed = {row[2] for row in categories}
assets = {}
with zipfile.ZipFile(io.BytesIO(base64.b64decode(ASSETS_B64))) as archive:
    if set(archive.namelist()) != allowed:
        raise SystemExit("Afbeeldingspakket ongeldig. Er is niets gewijzigd.")
    for name in allowed:
        content = archive.read(name)
        if content[:4] != b"RIFF" or content[8:12] != b"WEBP":
            raise SystemExit("WebP-afbeelding ongeldig: " + name)
        assets[name] = content
for path in (p,contact):
    if path.exists():
        backup=Path(str(path)+".before-categoriefotos.bak")
        if not backup.exists():backup.write_text(path.read_text(encoding="utf-8"),encoding="utf-8")
for name,content in assets.items():
    Path(name).write_bytes(content)
p.write_text(html,encoding="utf-8")
if contact_html is not None:
    contact.write_text(contact_html,encoding="utf-8")
print("Klaar: 8 klikbare categoriekaarten met WebP-foto's, productfilters en aanvraaglinks.")
print("Bestaande producten en zoekfunctie behouden. Nog niet gepubliceerd.")
